#!/usr/bin/env python3
"""Apply the Cover Stock compatibility / inventory UI separation patch."""
from __future__ import annotations
import argparse, json, shutil, sys
from datetime import datetime
from pathlib import Path

SEARCH_SCREEN = "import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\n\nimport '../data/models.dart';\nimport '../providers/app_controller.dart';\n\nclass SearchScreen extends ConsumerStatefulWidget {\n  const SearchScreen({super.key});\n\n  @override\n  ConsumerState<SearchScreen> createState() => _SearchScreenState();\n}\n\nclass _SearchScreenState extends ConsumerState<SearchScreen> {\n  final _searchController = TextEditingController();\n  final _focusNode = FocusNode();\n  int? _selectedModelId;\n\n  @override\n  void initState() {\n    super.initState();\n    WidgetsBinding.instance.addPostFrameCallback((_) {\n      if (mounted) _focusNode.requestFocus();\n    });\n  }\n\n  @override\n  void dispose() {\n    _searchController.dispose();\n    _focusNode.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final snapshot = ref.watch(appControllerProvider).value;\n    if (snapshot == null) {\n      return const Scaffold(body: Center(child: CircularProgressIndicator()));\n    }\n\n    final query = _searchController.text;\n    final selected =\n        _selectedModelId == null ? null : snapshot.modelFor(_selectedModelId!);\n    final matches = query.trim().isEmpty\n        ? const <DeviceModel>[]\n        : snapshot.searchModels(query);\n    final results = matches.take(30).toList(growable: false);\n\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('মিল যাচাই'),\n        actions: [\n          if (selected != null)\n            IconButton(\n              tooltip: 'অন্য মডেল খুঁজুন',\n              onPressed: () {\n                setState(() => _selectedModelId = null);\n                _focusNode.requestFocus();\n              },\n              icon: const Icon(Icons.swap_horiz_rounded),\n            ),\n        ],\n      ),\n      body: SafeArea(\n        top: false,\n        child: ListView(\n          padding: const EdgeInsets.fromLTRB(16, 4, 16, 28),\n          children: [\n            const Text(\n              'একটি মডেল লিখুন। তার COVER, GLASS ও LENS কোন কোন মডেলের সঙ্গে মেলে আলাদা করে দেখুন।',\n              style: TextStyle(fontSize: 13, height: 1.45),\n            ),\n            const SizedBox(height: 12),\n            TextField(\n              controller: _searchController,\n              focusNode: _focusNode,\n              textInputAction: TextInputAction.search,\n              onChanged: (_) => setState(() => _selectedModelId = null),\n              decoration: InputDecoration(\n                hintText: 'যেমন V20, Vivo V20 বা Galaxy S24',\n                prefixIcon: const Icon(Icons.search_rounded, size: 26),\n                suffixIcon: query.isEmpty\n                    ? null\n                    : IconButton(\n                        tooltip: 'মুছুন',\n                        onPressed: () {\n                          _searchController.clear();\n                          setState(() => _selectedModelId = null);\n                          _focusNode.requestFocus();\n                        },\n                        icon: const Icon(Icons.close_rounded),\n                      ),\n              ),\n            ),\n            if (selected == null && query.trim().isNotEmpty) ...[\n              const SizedBox(height: 18),\n              const Text(\n                'মডেল বাছাই করুন',\n                style: TextStyle(fontSize: 15, fontWeight: FontWeight.w800),\n              ),\n              const SizedBox(height: 8),\n              if (results.isEmpty)\n                const _EmptyState(\n                  title: 'মডেল পাওয়া যায়নি',\n                  message: 'অন্য বানানে বা সম্পূর্ণ ব্র্যান্ডসহ খুঁজুন।',\n                )\n              else\n                ...results.map((model) {\n                  final brand = snapshot.brandFor(model.brandId)?.name ?? '';\n                  return Card(\n                    margin: const EdgeInsets.only(bottom: 8),\n                    child: ListTile(\n                      title: Text(\n                        model.name,\n                        style: const TextStyle(fontWeight: FontWeight.w800),\n                      ),\n                      subtitle: Text([\n                        brand,\n                        model.deviceKind.label,\n                        if (model.releaseYear != null)\n                          model.releaseYear.toString(),\n                      ].join(' · ')),\n                      trailing: const Icon(Icons.chevron_right_rounded),\n                      onTap: () {\n                        setState(() => _selectedModelId = model.id);\n                        _focusNode.unfocus();\n                      },\n                    ),\n                  );\n                }),\n              if (matches.length > 30)\n                const Padding(\n                  padding: EdgeInsets.all(8),\n                  child: Text(\n                    'আরও ফলাফল আছে — আরও নির্দিষ্ট করে লিখুন।',\n                    textAlign: TextAlign.center,\n                  ),\n                ),\n            ] else if (selected != null) ...[\n              const SizedBox(height: 18),\n              Text(\n                snapshot.brandFor(selected.brandId)?.name ?? '',\n                style: TextStyle(\n                  color: Theme.of(context).colorScheme.primary,\n                  fontWeight: FontWeight.w700,\n                ),\n              ),\n              const SizedBox(height: 3),\n              Text(\n                selected.name,\n                style: const TextStyle(\n                  fontSize: 24,\n                  fontWeight: FontWeight.w900,\n                ),\n              ),\n              const SizedBox(height: 6),\n              Text(\n                'প্রতিটি category আলাদা। একটির মিল অন্য category-তে প্রযোজ্য নয়।',\n                style: TextStyle(\n                  color: Theme.of(context).colorScheme.onSurfaceVariant,\n                  fontSize: 12,\n                ),\n              ),\n              const SizedBox(height: 14),\n              ...selected.availableTypes.map((type) {\n                final alternatives =\n                    snapshot.alternativesFor(selected.id, type);\n                return _CompatibilitySection(\n                  type: type,\n                  alternatives: alternatives,\n                );\n              }),\n              const SizedBox(height: 8),\n              const _Notice(),\n            ] else ...[\n              const SizedBox(height: 30),\n              const _EmptyState(\n                title: 'মডেল খুঁজুন',\n                message:\n                    'উদাহরণ: V20 লিখে Vivo V20 নির্বাচন করুন। তারপর COVER, GLASS ও LENS-এর আলাদা ফলাফল দেখুন।',\n              ),\n              const SizedBox(height: 12),\n              const _Notice(),\n            ],\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nclass _CompatibilitySection extends StatelessWidget {\n  const _CompatibilitySection({\n    required this.type,\n    required this.alternatives,\n  });\n\n  final ItemType type;\n  final List<CompatibilitySuggestion> alternatives;\n\n  @override\n  Widget build(BuildContext context) {\n    final colorScheme = Theme.of(context).colorScheme;\n    return Card(\n      margin: const EdgeInsets.only(bottom: 12),\n      child: Padding(\n        padding: const EdgeInsets.all(14),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.stretch,\n          children: [\n            Row(\n              children: [\n                Container(\n                  padding:\n                      const EdgeInsets.symmetric(horizontal: 10, vertical: 7),\n                  decoration: BoxDecoration(\n                    color: colorScheme.secondaryContainer,\n                    borderRadius: BorderRadius.circular(10),\n                  ),\n                  child: Text(\n                    type.key,\n                    style: TextStyle(\n                      color: colorScheme.onSecondaryContainer,\n                      fontWeight: FontWeight.w900,\n                    ),\n                  ),\n                ),\n                const SizedBox(width: 10),\n                Expanded(\n                  child: Text(\n                    type.label,\n                    style: const TextStyle(\n                      fontSize: 16,\n                      fontWeight: FontWeight.w800,\n                    ),\n                  ),\n                ),\n                Text(\n                  '${alternatives.length}',\n                  style: TextStyle(\n                    color: colorScheme.onSurfaceVariant,\n                    fontWeight: FontWeight.w700,\n                  ),\n                ),\n              ],\n            ),\n            const SizedBox(height: 10),\n            if (alternatives.isEmpty)\n              Text(\n                'এই category-র verified compatibility data এখনো পাওয়া যায়নি। কোনো মিল অনুমান করে দেখানো হচ্ছে না।',\n                style: TextStyle(\n                  color: colorScheme.onSurfaceVariant,\n                  fontSize: 13,\n                  height: 1.4,\n                ),\n              )\n            else\n              ...alternatives.map((suggestion) {\n                final sure = suggestion.confidence == FitConfidence.sure;\n                return ListTile(\n                  contentPadding: EdgeInsets.zero,\n                  dense: true,\n                  leading: Icon(\n                    sure\n                        ? Icons.verified_rounded\n                        : Icons.fact_check_outlined,\n                    color: sure\n                        ? const Color(0xFF23864A)\n                        : const Color(0xFFB77900),\n                  ),\n                  title: Text(\n                    '${suggestion.brandName} ${suggestion.model.name}',\n                    style: const TextStyle(fontWeight: FontWeight.w700),\n                  ),\n                  subtitle: Text(\n                    sure\n                        ? '${suggestion.groupLabel} · verified source'\n                        : '${suggestion.groupLabel} · সম্ভাব্য মিল, আগে glass/cutout মিলিয়ে নিন',\n                    style: const TextStyle(fontSize: 11),\n                  ),\n                );\n              }),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nclass _EmptyState extends StatelessWidget {\n  const _EmptyState({required this.title, required this.message});\n\n  final String title;\n  final String message;\n\n  @override\n  Widget build(BuildContext context) {\n    return Container(\n      padding: const EdgeInsets.all(22),\n      decoration: BoxDecoration(\n        color: Theme.of(context).colorScheme.surfaceContainerHighest,\n        borderRadius: BorderRadius.circular(18),\n      ),\n      child: Column(\n        children: [\n          const Icon(Icons.search_rounded, size: 34),\n          const SizedBox(height: 10),\n          Text(title, style: const TextStyle(fontWeight: FontWeight.w800)),\n          const SizedBox(height: 5),\n          Text(\n            message,\n            textAlign: TextAlign.center,\n            style: TextStyle(\n              color: Theme.of(context).colorScheme.onSurfaceVariant,\n              fontSize: 12,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _Notice extends StatelessWidget {\n  const _Notice();\n\n  @override\n  Widget build(BuildContext context) {\n    return Container(\n      padding: const EdgeInsets.all(12),\n      decoration: BoxDecoration(\n        color: Theme.of(context)\n            .colorScheme\n            .secondaryContainer\n            .withValues(alpha: 0.45),\n        borderRadius: BorderRadius.circular(14),\n      ),\n      child: const Text(\n        'Compatibility data source-based, but may still be wrong. '\n        'A model name or screen size alone does not prove a fit. '\n        'Check the exact part, cutout and body shape before giving it to a customer.',\n        style: TextStyle(fontSize: 12, height: 1.4),\n      ),\n    );\n  }\n}\n"
DATABASE_METHOD = "\n  Future<void> mergeBundledCompatibilityCatalog() async {\n    final raw = await rootBundle.loadString('assets/compatibility_catalog.json');\n    final decoded = jsonDecode(raw);\n    if (decoded is! Map<String, dynamic> || decoded['groups'] is! List) return;\n\n    final modelVersionRows = await db.query(\n      'settings',\n      columns: ['value'],\n      where: 'key = ?',\n      whereArgs: ['catalog_version'],\n      limit: 1,\n    );\n    final modelVersion = modelVersionRows.isEmpty\n        ? 'unknown-model-catalog'\n        : modelVersionRows.first['value'].toString();\n    final compatibilityVersion =\n        decoded['catalogVersion']?.toString() ?? 'starter';\n    final mergedVersion = '$modelVersion:$compatibilityVersion';\n\n    final savedRows = await db.query(\n      'settings',\n      columns: ['value'],\n      where: 'key = ?',\n      whereArgs: ['compatibility_catalog_version'],\n      limit: 1,\n    );\n    if (savedRows.isNotEmpty && savedRows.first['value'] == mergedVersion) {\n      return;\n    }\n\n    await db.transaction((txn) async {\n      final rows = await txn.rawQuery('''\n        SELECT models.id, models.name, models.device_kind, brands.name AS brand_name\n        FROM models\n        INNER JOIN brands ON brands.id = models.brand_id\n      ''');\n      final modelIds = <String, int>{};\n      final modelKinds = <int, String>{};\n      for (final row in rows) {\n        final id = row['id'] as int;\n        final brand = normalizeSearch(row['brand_name']?.toString() ?? '');\n        final model = normalizeSearch(row['name']?.toString() ?? '');\n        modelIds['$brand:$model'] = id;\n        modelKinds[id] = row['device_kind']?.toString().toUpperCase() ?? 'PHONE';\n      }\n\n      final wrongRows = await txn.query('compatibility_wrong');\n      final blockedPairs = <String>{\n        for (final row in wrongRows)\n          pairKey(\n            ItemTypeText.parse(row['item_type']),\n            row['model_a'] as int,\n            row['model_b'] as int,\n          ),\n      };\n\n      for (final rawGroup in decoded['groups'] as List<dynamic>) {\n        if (rawGroup is! Map<String, dynamic>) continue;\n\n        final itemTypeText = rawGroup['itemType']?.toString().trim().toUpperCase();\n        ItemType? itemType;\n        for (final candidate in ItemType.values) {\n          if (candidate.key == itemTypeText) itemType = candidate;\n        }\n        if (itemType == null) continue;\n\n        final confidenceText =\n            rawGroup['confidence']?.toString().trim().toUpperCase();\n        if (confidenceText != 'SURE' && confidenceText != 'NINETY') continue;\n        final confidence = confidenceText == 'SURE'\n            ? FitConfidence.sure\n            : FitConfidence.ninety;\n        final label = rawGroup['label']?.toString().trim() ?? '';\n        final evidenceNote =\n            rawGroup['evidenceNote']?.toString().trim() ?? '';\n        if (label.isEmpty || evidenceNote.length < 12) continue;\n\n        final urls = <String>[];\n        final domains = <String>{};\n        final rawUrls = rawGroup['evidenceUrls'];\n        if (rawUrls is List) {\n          for (final value in rawUrls) {\n            final url = value.toString().trim();\n            final parsed = Uri.tryParse(url);\n            if (parsed == null ||\n                (parsed.scheme != 'http' && parsed.scheme != 'https') ||\n                parsed.host.isEmpty) {\n              continue;\n            }\n            if (urls.contains(url)) continue;\n            urls.add(url);\n            domains.add(parsed.host.toLowerCase());\n          }\n        }\n        if (confidence == FitConfidence.sure && domains.length < 2) continue;\n        if (confidence == FitConfidence.ninety && domains.isEmpty) continue;\n\n        final rawMembers = rawGroup['members'];\n        if (rawMembers is! List) continue;\n        final memberIds = <int>[];\n        var unresolved = false;\n        var containsTabletLens = false;\n\n        for (final rawMember in rawMembers) {\n          if (rawMember is! Map<String, dynamic>) {\n            unresolved = true;\n            break;\n          }\n          final brand = normalizeSearch(rawMember['brand']?.toString() ?? '');\n          final model = normalizeSearch(rawMember['model']?.toString() ?? '');\n          final id = modelIds['$brand:$model'];\n          if (id == null) {\n            unresolved = true;\n            break;\n          }\n          if (itemType == ItemType.lens && modelKinds[id] == 'TABLET') {\n            containsTabletLens = true;\n            break;\n          }\n          if (!memberIds.contains(id)) memberIds.add(id);\n        }\n\n        if (unresolved || containsTabletLens || memberIds.length < 2) continue;\n\n        var containsWrongPair = false;\n        for (var i = 0; i < memberIds.length; i++) {\n          for (var j = i + 1; j < memberIds.length; j++) {\n            if (blockedPairs.contains(pairKey(itemType, memberIds[i], memberIds[j]))) {\n              containsWrongPair = true;\n              break;\n            }\n          }\n          if (containsWrongPair) break;\n        }\n        if (containsWrongPair) continue;\n\n        final existingGroup = await txn.query(\n          'compatibility_groups',\n          columns: ['id'],\n          where: 'item_type = ? AND label = ?',\n          whereArgs: [itemType.key, label],\n          limit: 1,\n        );\n        if (existingGroup.isNotEmpty) continue;\n\n        var hasMembershipConflict = false;\n        for (final modelId in memberIds) {\n          final occupied = await txn.rawQuery('''\n            SELECT 1\n            FROM compatibility_members AS members\n            INNER JOIN compatibility_groups AS groups\n              ON groups.id = members.group_id\n            WHERE members.model_id = ? AND groups.item_type = ?\n            LIMIT 1\n          ''', [modelId, itemType.key]);\n          if (occupied.isNotEmpty) {\n            hasMembershipConflict = true;\n            break;\n          }\n        }\n        if (hasMembershipConflict) continue;\n\n        final groupId = await txn.insert('compatibility_groups', {\n          'item_type': itemType.key,\n          'label': label,\n          'evidence_urls': jsonEncode(urls),\n          'evidence_note': evidenceNote,\n        });\n        for (final modelId in memberIds) {\n          await txn.insert('compatibility_members', {\n            'group_id': groupId,\n            'model_id': modelId,\n            'confidence': confidence.key,\n          });\n        }\n      }\n\n      await txn.insert(\n        'settings',\n        {\n          'key': 'compatibility_catalog_version',\n          'value': mergedVersion,\n        },\n        conflictAlgorithm: ConflictAlgorithm.replace,\n      );\n    });\n  }\n\n"
COMPATIBILITY_CATALOG = {'schemaVersion': 1, 'catalogVersion': '2026-11-26-v1', 'sourceNote': 'Curated, category-specific candidate matches. Unknown fitments are intentionally omitted.', 'groups': [{'itemType': 'GLASS', 'label': 'K34 — Tempered Glass (conditional candidate)', 'confidence': 'NINETY', 'evidenceUrls': ['https://www.mobimatchpro.com/'], 'evidenceNote': "MobiMatch Pro's public K-code tempered-glass matrix places OPPO Reno3, Vivo S1 Pro, Vivo V20, Vivo V20 SE and Vivo V23e in K34. The page does not expose a supplier SKU or exact cutout dimensions for this group. Treat as a candidate only; compare glass outline, top cutout and borders before fitting.", 'members': [{'brand': 'Oppo', 'model': 'Reno3'}, {'brand': 'Vivo', 'model': 'S1 Pro'}, {'brand': 'Vivo', 'model': 'V20'}, {'brand': 'Vivo', 'model': 'V20 SE'}, {'brand': 'Vivo', 'model': 'V23e'}]}]}

WIDGET_TEST = """import 'package:cover_stock/data/models.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('the app has separate accessory categories', () {
    expect(ItemType.values, [ItemType.cover, ItemType.glass, ItemType.lens]);
  });

  test('tablets do not expose camera lens compatibility', () {
    const tablet = DeviceModel(
      id: 1,
      brandId: 1,
      name: 'Test Tablet',
      deviceKind: DeviceKind.tablet,
      stock: {},
    );
    expect(tablet.availableTypes, [ItemType.cover, ItemType.glass]);
  });
}
"""


def read_text(path):
    if not path.is_file():
        raise RuntimeError(f'Required file is missing: {path}')
    return path.read_text(encoding='utf-8')

def replace_once(source, old, new, label):
    count = source.count(old)
    if count != 1:
        raise RuntimeError(f'Expected exactly one target in {label}, found {count}. No files changed.')
    return source.replace(old, new, 1)

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('project_root', nargs='?', default='.')
    root = Path(parser.parse_args().project_root).resolve()
    required = ['lib/screens/search_screen.dart', 'lib/data/models.dart', 'lib/data/app_database.dart', 'lib/app.dart', 'pubspec.yaml', 'test/models_test.dart']
    missing = [p for p in required if not (root / p).is_file()]
    if missing: raise RuntimeError('Not a Cover Stock project. Missing: ' + ', '.join(missing))

    old_search = read_text(root / 'lib/screens/search_screen.dart')
    if 'class SearchScreen extends ConsumerStatefulWidget' not in old_search: raise RuntimeError('Unexpected SearchScreen implementation.')
    new_search = SEARCH_SCREEN

    old_models = read_text(root / 'lib/data/models.dart')
    new_models = replace_once(old_models, 'if (other == null || other.count(type) <= 0) continue;', 'if (other == null) continue;', 'lib/data/models.dart')

    old_db = read_text(root / 'lib/data/app_database.dart')
    new_db = replace_once(old_db, '    await instance.mergeBundledCatalog();\n    return instance;', '    await instance.mergeBundledCatalog();\n    await instance.mergeBundledCompatibilityCatalog();\n    return instance;', 'lib/data/app_database.dart')
    if 'Future<void> mergeBundledCompatibilityCatalog()' in new_db: raise RuntimeError('Compatibility merge already exists.')
    new_db = replace_once(new_db, '  static int? _parseYear(Object? value) {', DATABASE_METHOD + '  static int? _parseYear(Object? value) {', 'lib/data/app_database.dart')

    old_app = read_text(root / 'lib/app.dart')
    new_app = replace_once(old_app, "NavigationDestination(icon: Icon(Icons.search_rounded), label: 'খুঁজুন'),", "NavigationDestination(icon: Icon(Icons.compare_arrows_rounded), label: 'মিল যাচাই'),", 'lib/app.dart')

    old_pubspec = read_text(root / 'pubspec.yaml')
    new_pubspec = replace_once(old_pubspec, '    - assets/model_catalog.json', '    - assets/model_catalog.json\n    - assets/compatibility_catalog.json', 'pubspec.yaml')

    old_test = read_text(root / 'test/models_test.dart')
    new_test = replace_once(old_test, "test('sure alternatives sort before ninety-percent alternatives', () {", "test('compatibility results are independent of inventory stock', () {", 'test/models_test.dart')
    new_test = replace_once(new_test, "DeviceModel(id: 2, brandId: 1, name: 'V20 SE', stock: {ItemType.glass: 4}),", "DeviceModel(id: 2, brandId: 1, name: 'V20 SE', stock: {ItemType.glass: 0}),", 'test/models_test.dart')
    new_test = replace_once(new_test, "DeviceModel(id: 3, brandId: 1, name: 'Y73', stock: {ItemType.glass: 3}),", "DeviceModel(id: 3, brandId: 1, name: 'Y73', stock: {ItemType.glass: 0}),", 'test/models_test.dart')

    updates = {
        'lib/screens/search_screen.dart': new_search,
        'lib/data/models.dart': new_models,
        'lib/data/app_database.dart': new_db,
        'lib/app.dart': new_app,
        'pubspec.yaml': new_pubspec,
        'test/models_test.dart': new_test,
        'test/widget_test.dart': WIDGET_TEST,
        'assets/compatibility_catalog.json': json.dumps(COMPATIBILITY_CATALOG, ensure_ascii=False, indent=2) + '\n',
    }
    # Keep project documentation aligned with the new runtime behaviour.
    readme_path = root / 'README.md'
    if readme_path.is_file():
        readme_text = read_text(readme_path)
        old_compat = '2. **Accessory compatibility:** TechAPI supplies device identity/specification records; it does not supply trustworthy Cover/Glass/Lens cross-fit mappings. This project does **not** guess that two models share a part. No compatibility groups are seeded. Groups must come from a reliable exact part/SKU compatibility list or a physical fit check, and they must be imported or entered separately.'
        new_compat = '2. **Accessory compatibility:** This is a separate, category-specific dataset in `assets/compatibility_catalog.json`, auto-merged into SQLite at startup for offline use. The initial V20 GLASS group is a conditional K34 source reference only; it is not a physical-fit guarantee. No V20 COVER or LENS cross-model match is included because a trustworthy source was not found. Unknown fits stay unlisted.'
        readme_text = replace_once(readme_text, old_compat, new_compat, 'README.md compatibility policy')
        readme_text = replace_once(readme_text, '- Material 3 interface with four tabs: Search, Stock, Order List and Settings. Search opens first and gets keyboard focus.', '- Material 3 interface with four tabs: Compatibility Check, Stock, Order List and Settings. Compatibility Check is read-only; stock changes happen only in Stock.', 'README.md tabs')
        readme_text = replace_once(readme_text, '- Alternative suggestions are based only on compatibility groups already stored locally. SURE sorts first; NINETY displays a check-before-giving warning. Selling an alternative reduces stock for that alternative model.', '- Compatibility results are displayed independently of stock quantities. SURE sorts first; NINETY is shown as a conditional match. Add/Sell controls exist only in the Stock tab.', 'README.md compatibility feature')
        updates['README.md'] = readme_text

    handoff_path = root / 'HANDOFF.md'
    if handoff_path.is_file():
        handoff_text = read_text(handoff_path)
        handoff_text = replace_once(handoff_text, "TechAPI doesn't supply verified cross-fit compatibility for covers, screen protectors or camera protectors. Seed groups are intentionally empty. Do not generate mappings by screen diagonal or model-family similarity alone.", "TechAPI does not supply accessory fitment. A separate bundled `assets/compatibility_catalog.json` is auto-merged by `mergeBundledCompatibilityCatalog()`. The initial V20 K34 GLASS entry is conditional and source-based, not physically verified. No V20 COVER/LENS match is seeded. Never infer cross-fit from screen size or model-family similarity.", 'HANDOFF.md compatibility policy')
        handoff_text = replace_once(handoff_text, "No accessory compatibility map is bundled because no source in this project reliably proves general cross-model Cover/Glass/Lens equivalence. Compatibility is evidence-based and owner-reviewed.", "The bundled compatibility map is intentionally small. Current known entry: conditional V20-family K34 tempered GLASS reference. No V20 COVER or LENS cross-fit is bundled. Add only category-specific matches with source evidence; keep unknown relationships empty.", 'HANDOFF.md remaining limits')
        updates['HANDOFF.md'] = handoff_text
    backup = root / ('.cover-stock-backup-' + datetime.now().strftime('%Y%m%d-%H%M%S'))
    backup.mkdir(parents=True, exist_ok=False)
    for name in updates:
        path = root / name
        if path.exists():
            target = backup / name
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, target)
    try:
        for name, content in updates.items():
            path = root / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding='utf-8')
    except Exception:
        for name in updates:
            saved = backup / name
            if saved.exists(): shutil.copy2(saved, root / name)
        raise
    print('Patch applied successfully.')
    print(f'Backup saved to: {backup}')
    print('Changed files:')
    for name in updates: print('  ' + name)
    print('Next: run git diff --check, commit and push. GitHub Actions will run Flutter tests/analyze and build the APK.')
    return 0

if __name__ == '__main__':
    try: raise SystemExit(main())
    except Exception as error:
        print(f'ERROR: {error}', file=sys.stderr)
        raise SystemExit(1)
